-- =====================================================================
-- TRAINING LIBRARY SLICE 1-DB — the real catalog (library_drills) + "pull into my plans".   DRAFT — NOT APPLIED. NOT REVIEWED.
-- GENERATED by docs/review/library_s1_build.mjs from this template + the 6 SEED packets in src/App.jsx (verbatim content).
-- Edit the template/generator, not the generated file.
-- Rulings: claude/B4C_TrainingLibrary_Step0_ReviewRecord.md (L0/L1 one library as a Training tab; L2/L4 PA curates — the
-- curator flow itself is slice 2; L3 "used" = attached + done + attended + not cancelled; L5 snapshots; L8 no back-fill).
-- Pins read LIVE 2026-10-27 (docs/review/library_s1_LIVEDEFS.sql -> _LIVEDEFS.json).
--
-- ONE ALL-OR-NOTHING DO BLOCK, then NOTIFY pgrst, then a read-only state row. RETEST separately
-- (sql/library_s1_catalog_RETEST.sql, SENTINEL). Dry run: docs/review/library_s1_dryrun_harness.mjs.
--
-- WHAT IT DOES (additive; no existing policy, function or row changes — except the one pinned CHECK widening below)
--   library_drills        GLOBAL catalog (no department_id — the standard_cert_types pattern). code, title, track
--                         (Fire|EMS|Leadership|Operations), level, duration_min, audience, content (jsonb, the drill_plans
--                         shape + the packet-only keys), origin (seed|ai_drop|shared), origin_department_id (NOT selectable),
--                         credit_name (opt-in, slice 2), state (submitted|published|withdrawn), content_hash (generated,
--                         UNIQUE — dedupe), published_at/by. RLS: SELECT TO authenticated USING (state = 'published').
--                         Column grants: every column EXCEPT origin_department_id; no write grant (seed here; curator RPCs
--                         are slice 2). anon: nothing.
--   seed                  the 6 hard-coded SEED packets (App.jsx) as origin='seed', state='published' — the existing nav
--                         "Training Library" gets a real backing table (L0).
--   drill_plans           + library_id uuid → library_drills ON DELETE SET NULL (the copy's link back, for "used");
--                         source CHECK widened ai|manual → ai|manual|library (pinned drop + re-add); + CHECK library_id
--                         set ⇒ source = 'library'.
--   pull_library_drill(id)   is_training_manager() + own department: copies a PUBLISHED catalog drill into the caller's
--                         drill_plans as a DRAFT (source 'library', library_id set) — their officer approves before use.
--                         Refuses a second pull of the same drill (ALREADY_PULLED).
--   library_drill_usage()  counts only: per published drill, held sessions + distinct departments (L3) — never which
--                         department, never who. Needs a member (my_member_id()).
--
-- DECISIONS FOR THE GATE REVIEW (claude/B4C_TrainingLibrary_S1_DB_Draft.md):
--   D1 Seed content mapping: objective → summary; evaluation → objectives; steps → run_of_show ("<step> — N min");
--      equipment → materials; safety → safety; instructorGuide / scenario / discussion / debrief kept as extra keys
--      (instructor_guide, scenario, discussion, debrief, evaluation). drill_plans' CHECK only requires an object.
--   D2 No catalog write path in this slice (no INSERT/UPDATE grant, no curator RPC). PA curation, sharing, the AI drop =
--      slices 2-3. The 6 seed rows are the whole catalog until then.
--   D3 Duplicate pull → ALREADY_PULLED (not a second copy). A department that deleted its copy can pull again.
--   D4 content_hash = md5(lower(btrim(title)) || '|' || content::text), a GENERATED column, UNIQUE.
--   D5 library_drill_usage() counts across ALL departments (that's the point — "held N times in M departments") but returns
--      only integers per catalog row.
-- =====================================================================

DO $mig$
DECLARE
  v_pins constant jsonb := jsonb_build_object(
    'public.approve_drill_plan(uuid)', 'a01c872bc14561fcb633796353a4b694',
    'public.attach_drill_plan_to_session(uuid,uuid)', 'a2fa184580b3be907d9dad944775c6a2',
    'public.delete_drill_plan(uuid)', 'fc5a12df02bf1216815c361f985aaa1b',
    'public.dept_drill_plans()', 'd786d5593ef494c71549054d85864c8c',
    'public.is_training_manager()', '472b87b0abca586ba0a13cd615b376fe',
    'public.is_training_officer()', '248392a51fe913771f725b2a51013302',
    'public.my_department_id()', '87f546659c3804a943b48e419e017f18',
    'public.my_member_id()', '3f66369c8af7bc07ec59831af6536fee',
    'public.set_drill_plan(uuid,text,text,integer,text,jsonb,text)', 'f574003f5c6905d120fd6365a1b7ce11',
    'public.unapprove_drill_plan(uuid)', '6012d001e95c3a5d6bdd0f6a49e8daf0');
  v_src_old constant text := 'CHECK ((source = ANY (ARRAY[''ai''::text, ''manual''::text])))';
  v_pol_old constant text := 'members read drill_plans|SELECT|authenticated|(department_id = my_department_id())|';
  v_new_fns constant text[] := array['pull_library_drill', 'library_drill_usage'];
  v_fn_before text; v_fn_after text; v_pol_before text; v_pol_after text; v_acl_before text; v_acl_after text;
  v_con_before text; v_con_after text; v_trg_before text; v_trg_after text; v_ver_before bigint; v_ver_after bigint;
  k text; v text; v_n int;
BEGIN
  -- ---------------------------------------------------------------- 0. pre-flight
  IF to_regclass('public.library_drills') IS NOT NULL THEN RAISE EXCEPTION 'PREFLIGHT: library_drills already exists — slice 1 looks applied. Refusing.'; END IF;
  IF EXISTS (SELECT 1 FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname = ANY (v_new_fns)) THEN
    RAISE EXCEPTION 'PREFLIGHT: a slice-1 function name already exists. Refusing.';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public.drill_plans'::regclass AND attname = 'library_id' AND NOT attisdropped) THEN
    RAISE EXCEPTION 'PREFLIGHT: drill_plans.library_id already exists. Refusing.';
  END IF;
  FOR k, v IN SELECT * FROM jsonb_each_text(v_pins) LOOP
    IF to_regprocedure(k) IS NULL OR md5(pg_get_functiondef(to_regprocedure(k))) <> v THEN
      RAISE EXCEPTION 'PREFLIGHT: % is missing or has drifted (pinned %). Re-audit.', k, v;
    END IF;
  END LOOP;
  IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.drill_plans'::regclass AND conname = 'drill_plans_source_chk') IS DISTINCT FROM v_src_old THEN
    RAISE EXCEPTION 'PREFLIGHT: drill_plans_source_chk is not the audited text. Re-audit.';
  END IF;
  IF (SELECT string_agg(policyname || '|' || cmd || '|' || array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',')
        FROM pg_policies WHERE schemaname = 'public' AND tablename = 'drill_plans') IS DISTINCT FROM v_pol_old THEN
    RAISE EXCEPTION 'PREFLIGHT: drill_plans policies are not the audited single SELECT. Re-audit.';
  END IF;
  SELECT md5(string_agg(p.oid::regprocedure::text || '=' || md5(pg_get_functiondef(p.oid)) || '/' || coalesce(p.proacl::text, ''), ',' ORDER BY p.oid::regprocedure::text))
    INTO v_fn_before FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prokind IN ('f', 'p');
  SELECT md5(string_agg(tablename || '.' || policyname || '|' || cmd || '|' || array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',' ORDER BY tablename, policyname))
    INTO v_pol_before FROM pg_policies WHERE schemaname IN ('public', 'storage');
  SELECT md5(string_agg(c.relname || '=' || coalesce(c.relacl::text, '') || '/' || c.relrowsecurity, ',' ORDER BY c.relname))
    INTO v_acl_before FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'v', 'm');
  SELECT md5(string_agg(conrelid::regclass::text || '.' || conname || '=' || pg_get_constraintdef(oid), ',' ORDER BY conrelid::regclass::text, conname))
    INTO v_con_before FROM pg_constraint WHERE connamespace = 'public'::regnamespace AND NOT (conrelid = 'public.drill_plans'::regclass AND conname = 'drill_plans_source_chk');
  SELECT md5(string_agg(tgrelid::regclass::text || '.' || tgname || '=' || pg_get_triggerdef(oid) || '/' || tgenabled::text, ',' ORDER BY tgrelid::regclass::text, tgname))
    INTO v_trg_before FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'public'::regnamespace);
  SELECT count(*) INTO v_ver_before FROM public.station_presence WHERE verified;

  -- ---------------------------------------------------------------- 1. the catalog
  EXECUTE $ddl$
    CREATE TABLE public.library_drills (
      id                   uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
      code                 text        UNIQUE,
      title                text        NOT NULL CHECK (btrim(title) <> ''),
      track                text        NOT NULL CHECK (track IN ('Fire', 'EMS', 'Leadership', 'Operations')),
      level                text,
      duration_min         integer     CHECK (duration_min IS NULL OR duration_min BETWEEN 1 AND 1440),
      audience             text,
      content              jsonb       NOT NULL CHECK (jsonb_typeof(content) = 'object'),
      origin               text        NOT NULL DEFAULT 'seed' CHECK (origin IN ('seed', 'ai_drop', 'shared')),
      origin_department_id uuid        REFERENCES public.departments(id) ON DELETE SET NULL,
      credit_name          text,
      state                text        NOT NULL DEFAULT 'submitted' CHECK (state IN ('submitted', 'published', 'withdrawn')),
      content_hash         text        GENERATED ALWAYS AS (md5(lower(btrim(title)) || '|' || content::text)) STORED,
      published_at         timestamptz,
      published_by         uuid,
      created_at           timestamptz NOT NULL DEFAULT now(),
      updated_at           timestamptz NOT NULL DEFAULT now(),
      CONSTRAINT library_drills_content_hash_key UNIQUE (content_hash),
      CONSTRAINT library_drills_published_chk CHECK (state <> 'published' OR published_at IS NOT NULL)
    ) $ddl$;
  EXECUTE 'ALTER TABLE public.library_drills ENABLE ROW LEVEL SECURITY';
  EXECUTE 'REVOKE ALL ON TABLE public.library_drills FROM PUBLIC, anon, authenticated';
  EXECUTE 'REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON TABLE public.library_drills FROM service_role';
  EXECUTE 'GRANT SELECT (id, code, title, track, level, duration_min, audience, content, origin, credit_name, state, content_hash, published_at, created_at, updated_at) ON public.library_drills TO authenticated';
  EXECUTE $p$ CREATE POLICY "published library drills" ON public.library_drills FOR SELECT TO authenticated USING (state = 'published') $p$;

  -- ---------------------------------------------------------------- 2. the 6 seed packets (verbatim from App.jsx SEED)
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('FIRE-203', 'Primary Search & Rescue', 'Fire', 'Intermediate', 90, NULL, $seed${"summary":"Crews conduct a coordinated primary search with crew integrity, accountability, and a charged-line tie-in where required.","objectives":["Maintains crew contact throughout","Communicates air status","Follows accountability system"],"run_of_show":[{"t":"Briefing & accountability — 15 min","d":"Set crew assignments and the accountability system."},{"t":"Search patterns — 20 min","d":"Right/left-hand search, maintaining crew contact."},{"t":"Evolution — 35 min","d":"Two-in/two-out, oriented search of the prop."},{"t":"Debrief — 20 min","d":"Communication, air management, accountability gaps."}],"materials":["Full PPE / SCBA","Search rope / TIC if available","Accountability board"],"safety":["Assign a safety officer","No live fire in this drill","Confirm SCBA checks before entry","RIT/two-out in place"],"instructor_guide":"Live fire is NOT part of this drill. Run cold or in a smoke-free prop. A qualified safety officer must be assigned for any heat evolution.","scenario":"Reported occupant in a single-story residence, moderate (simulated) smoke. Conduct primary search.","discussion":["Where did crew integrity break down?","How was air management communicated?"],"debrief":["Did everyone know who was where?","What would you change on a real fireground?"],"evaluation":["Maintains crew contact throughout","Communicates air status","Follows accountability system"],"revised":"May 2026"}$seed$::jsonb, 'seed', 'published', now());
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('FIRE-118', 'Mayday Operations & Self-Survival', 'Fire', 'Intermediate', 75, NULL, $seed${"summary":"Members declare a Mayday correctly, perform self-survival actions, and practice the LUNAR sequence.","objectives":["Declares Mayday without prompting","Transmits LUNAR clearly","Performs self-survival steps"],"run_of_show":[{"t":"Why Mayday early — 15 min","d":"Discuss hesitation and the cost of delay."},{"t":"Declaration drill — 20 min","d":"Radio Mayday with LUNAR information."},{"t":"Self-survival — 25 min","d":"Reduced profile, SCBA emergency procedures."},{"t":"Debrief — 15 min","d":"What made declaring hard?"}],"materials":["Full PPE / SCBA","Radios","Reduced-profile prop"],"safety":["Assign a safety officer","No live fire","Medical standby for strenuous evolutions"],"instructor_guide":"Keep it low-stress and repeatable. The goal is muscle memory, not a gauntlet. No fire.","scenario":"Firefighter disoriented and low on air during search. Declare and self-rescue.","discussion":["Why do firefighters delay calling Mayday?","What does command need to hear first?"],"debrief":["Did you hesitate? Why?","Was your transmission clear under stress?"],"evaluation":["Declares Mayday without prompting","Transmits LUNAR clearly","Performs self-survival steps"],"revised":"Mar 2026"}$seed$::jsonb, 'seed', 'published', now());
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('EMS-114', 'Stroke Recognition (BE-FAST)', 'EMS', 'All levels', 60, NULL, $seed${"summary":"Members identify stroke signs using BE-FAST, document last-known-well time, and select the correct destination per regional protocol.","objectives":["Completes BE-FAST in order","Documents last-known-well","States correct destination"],"run_of_show":[{"t":"Briefing — 10 min","d":"Field-level stroke pathophysiology and why last-known-well matters."},{"t":"BE-FAST walkthrough — 15 min","d":"Demonstrate each element; practice on a volunteer."},{"t":"Scenario A — 12 min","d":"Posterior stroke presenting as dizziness."},{"t":"Scenario B — 12 min","d":"Facial droop with uncertain onset."},{"t":"Debrief — 11 min","d":"Documentation and destination decisions."}],"materials":["Stroke scale cards","Simulated patient","Run report forms"],"safety":["Confirm scene safety","Standard BSI precautions"],"instructor_guide":"Open with why time-to-treatment drives outcomes. Run two short scenarios, then debrief documentation.","scenario":"Family reports a 71-year-old 'not acting right' since waking. Establish last-known-well and assess.","discussion":["What complicates establishing last-known-well?","When does your region bypass to a stroke center?"],"debrief":["What slowed your assessment?","Was destination selection clear?"],"evaluation":["Completes BE-FAST in order","Documents last-known-well","States correct destination"],"revised":"May 2026"}$seed$::jsonb, 'seed', 'published', now());
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('EMS-203', 'Pediatric Emergencies — Assessment Triangle', 'EMS', 'All levels', 75, NULL, $seed${"summary":"Members apply the Pediatric Assessment Triangle, size equipment correctly, and adjust communication for caregivers.","objectives":["Forms doorway impression first","Sizes equipment correctly","Communicates clearly"],"run_of_show":[{"t":"PAT overview — 15 min","d":"Appearance, work of breathing, circulation to skin."},{"t":"Equipment sizing — 20 min","d":"Length-based tape drills, repeat for speed."},{"t":"Scenario — 20 min","d":"Febrile seizure with anxious caregiver."},{"t":"Debrief — 20 min","d":"Caregiver communication and transport."}],"materials":["Length-based tape","Pediatric BVM","Sim doll if available"],"safety":["Scene safety","BSI precautions","Keep caregiver involved to reduce child distress"],"instructor_guide":"Emphasize the from-the-doorway impression before touching the child. Practice sizing under time pressure.","scenario":"2-year-old post-seizure, now postictal. Caregiver is panicking.","discussion":["How does caregiver anxiety affect your assessment?","When is rapid transport warranted?"],"debrief":["What was hardest under time pressure?","Did you size gear right the first try?"],"evaluation":["Forms doorway impression first","Sizes equipment correctly","Communicates clearly"],"revised":"Apr 2026"}$seed$::jsonb, 'seed', 'published', now());
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('LEAD-140', 'Volunteer Retention — Stay Conversations', 'Leadership', 'Officers', 60, NULL, $seed${"summary":"Officers run a structured 'stay interview' and identify the top three drivers pushing members out.","objectives":["Asks open questions","Listens more than talks","Leaves with a follow-up"],"run_of_show":[{"t":"The cost of turnover — 10 min","d":"What it takes to replace a trained member."},{"t":"Stay-interview structure — 15 min","d":"Five questions that surface real friction."},{"t":"Role-play — 20 min","d":"Pairs practice both sides."},{"t":"Action planning — 15 min","d":"Each officer commits to two conversations."}],"materials":["Stay-interview question sheet","Whiteboard"],"safety":["Keep conversations confidential and judgment-free"],"instructor_guide":"Frame retention as cheaper than recruitment. Role-play the conversation; it's harder than it looks.","scenario":"A reliable five-year member has quietly stopped showing up. Re-engage without guilt-tripping.","discussion":["What pushes good members out?","Do you lose people in year one or year five?"],"debrief":["What surprised you?","Which driver shows up most here?"],"evaluation":["Asks open questions","Listens more than talks","Leaves with a follow-up"],"revised":"Apr 2026"}$seed$::jsonb, 'seed', 'published', now());
  INSERT INTO public.library_drills (code, title, track, level, duration_min, audience, content, origin, state, published_at)
  VALUES ('OPS-120', 'Run It Like a Business — Annual Operating Plan', 'Operations', 'Chiefs & Admin', 75, NULL, $seed${"summary":"Leadership builds a one-page operating plan: budget, funding sources, staffing targets, and key metrics — mission-first, run with business discipline.","objectives":["Identifies all funding sources","Sets staffing targets","Names three review metrics"],"run_of_show":[{"t":"Money in, money out — 20 min","d":"Map funding sources against costs."},{"t":"People plan — 20 min","d":"Set staffing and a recruitment/retention number."},{"t":"Pick 3 metrics — 15 min","d":"Three numbers leadership reviews monthly."},{"t":"Reporting cadence — 20 min","d":"What the board / municipality sees, and when."}],"materials":["Operating-plan template","Prior-year budget","Call volume data"],"safety":["Keep financial and personnel records per agency policy and law"],"instructor_guide":"Not about going corporate — about clarity: where money comes from, where people come from, and how you know it's working.","scenario":"The municipality asks for a one-page plan justifying next year's funding. Build it.","discussion":["What single number best shows your department is healthy?","Where is funding most fragile?"],"debrief":["Where's your biggest financial risk?","Who owns this plan after today?"],"evaluation":["Identifies all funding sources","Sets staffing targets","Names three review metrics"],"revised":"Jun 2026"}$seed$::jsonb, 'seed', 'published', now());

  -- ---------------------------------------------------------------- 3. drill_plans: the link back + the 'library' source
  EXECUTE 'ALTER TABLE public.drill_plans ADD COLUMN library_id uuid REFERENCES public.library_drills(id) ON DELETE SET NULL';
  EXECUTE 'CREATE INDEX drill_plans_library_idx ON public.drill_plans (library_id) WHERE library_id IS NOT NULL';
  EXECUTE 'ALTER TABLE public.drill_plans DROP CONSTRAINT drill_plans_source_chk';
  EXECUTE $c$ ALTER TABLE public.drill_plans ADD CONSTRAINT drill_plans_source_chk CHECK (source = ANY (ARRAY['ai'::text, 'manual'::text, 'library'::text])) $c$;
  EXECUTE $c$ ALTER TABLE public.drill_plans ADD CONSTRAINT drill_plans_library_source_chk CHECK (library_id IS NULL OR source = 'library') $c$;

  -- ---------------------------------------------------------------- 4. pull + usage
  EXECUTE $fn$
    CREATE FUNCTION public.pull_library_drill(p_library_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $body$
    -- B4C:library slice 1 — copy a PUBLISHED catalog drill into MY department's drill plans as a DRAFT (a snapshot, L5).
    DECLARE
      v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id();
      l public.library_drills; v_id uuid;
    BEGIN
      IF v_dept IS NULL OR v_me IS NULL OR NOT coalesce(public.is_training_manager(), false) THEN
        RAISE EXCEPTION 'NOT_ALLOWED: only a Department Admin or training officer can add library drills to your plans.';
      END IF;
      SELECT * INTO l FROM public.library_drills WHERE id = p_library_id AND state = 'published';
      IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: that drill is not in the library.' USING errcode = 'P0002'; END IF;
      SELECT id INTO v_id FROM public.drill_plans WHERE department_id = v_dept AND library_id = l.id LIMIT 1;
      IF FOUND THEN RAISE EXCEPTION 'ALREADY_PULLED: that drill is already in your plans.'; END IF;
      INSERT INTO public.drill_plans (department_id, title, category, duration_min, audience, content, status, source, library_id, created_by, updated_by)
      VALUES (v_dept, l.title, NULL, l.duration_min, l.audience, l.content, 'draft', 'library', l.id, v_me, v_me)
      RETURNING id INTO v_id;
      RETURN v_id;
    END $body$ $fn$;
  EXECUTE $fn$
    CREATE FUNCTION public.library_drill_usage() RETURNS TABLE (library_id uuid, held integer, departments integer)
      LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $body$
    -- B4C:library slice 1 — "used" (L3) = a copy attached to a session that was finalized, not cancelled, and attended.
    -- COUNTS ONLY: never which department, never who. Members only (a stray login gets nothing).
      SELECT l.id,
             count(DISTINCT s.id)::int,
             count(DISTINCT s.department_id)::int
        FROM public.library_drills l
        JOIN public.drill_plans dp ON dp.library_id = l.id
        JOIN public.session_plans sp ON sp.drill_plan_id = dp.id AND sp.department_id = dp.department_id
        JOIN public.training_sessions s ON s.id = sp.session_id AND s.department_id = dp.department_id
       WHERE public.my_member_id() IS NOT NULL
         AND l.state = 'published' AND s.done AND s.status <> 'cancelled'
         AND EXISTS (SELECT 1 FROM public.session_attendance a WHERE a.session_id = s.id)
       GROUP BY l.id
    $body$ $fn$;
  FOREACH k IN ARRAY array['public.pull_library_drill(uuid)', 'public.library_drill_usage()'] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon', k);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', k);
  END LOOP;

  -- ---------------------------------------------------------------- 5. post-conditions
  SELECT md5(string_agg(p.oid::regprocedure::text || '=' || md5(pg_get_functiondef(p.oid)) || '/' || coalesce(p.proacl::text, ''), ',' ORDER BY p.oid::regprocedure::text))
    INTO v_fn_after FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prokind IN ('f', 'p') AND NOT (p.proname = ANY (v_new_fns));
  IF v_fn_after <> v_fn_before THEN RAISE EXCEPTION 'POST: a pre-existing function (or its ACL) changed — it must not.'; END IF;
  SELECT md5(string_agg(tablename || '.' || policyname || '|' || cmd || '|' || array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',' ORDER BY tablename, policyname))
    INTO v_pol_after FROM pg_policies WHERE schemaname IN ('public', 'storage') AND tablename <> 'library_drills';
  IF v_pol_after <> v_pol_before THEN RAISE EXCEPTION 'POST: a pre-existing policy changed — it must not.'; END IF;
  SELECT md5(string_agg(c.relname || '=' || coalesce(c.relacl::text, '') || '/' || c.relrowsecurity, ',' ORDER BY c.relname))
    INTO v_acl_after FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'v', 'm') AND c.relname <> 'library_drills';
  IF v_acl_after <> v_acl_before THEN RAISE EXCEPTION 'POST: a pre-existing table''s grants / RLS changed.'; END IF;
  SELECT md5(string_agg(conrelid::regclass::text || '.' || conname || '=' || pg_get_constraintdef(oid), ',' ORDER BY conrelid::regclass::text, conname))
    INTO v_con_after FROM pg_constraint WHERE connamespace = 'public'::regnamespace AND conrelid <> 'public.library_drills'::regclass
     AND NOT (conrelid = 'public.drill_plans'::regclass AND conname IN ('drill_plans_source_chk', 'drill_plans_library_source_chk', 'drill_plans_library_id_fkey'));
  IF v_con_after <> v_con_before THEN RAISE EXCEPTION 'POST: a pre-existing constraint changed.'; END IF;
  SELECT md5(string_agg(tgrelid::regclass::text || '.' || tgname || '=' || pg_get_triggerdef(oid) || '/' || tgenabled::text, ',' ORDER BY tgrelid::regclass::text, tgname))
    INTO v_trg_after FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'public'::regnamespace);
  IF v_trg_after <> v_trg_before THEN RAISE EXCEPTION 'POST: a trigger changed.'; END IF;
  IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.drill_plans'::regclass AND conname = 'drill_plans_source_chk')
       <> 'CHECK ((source = ANY (ARRAY[''ai''::text, ''manual''::text, ''library''::text])))' THEN
    RAISE EXCEPTION 'POST: drill_plans_source_chk not as intended.';
  END IF;
  SELECT count(*) INTO v_n FROM public.library_drills WHERE origin = 'seed' AND state = 'published';
  IF v_n <> 6 THEN RAISE EXCEPTION 'POST: expected 6 published seed drills, found %.', v_n; END IF;
  IF has_table_privilege('anon', 'public.library_drills', 'SELECT') OR has_table_privilege('authenticated', 'public.library_drills', 'INSERT')
     OR has_table_privilege('authenticated', 'public.library_drills', 'UPDATE') OR has_table_privilege('authenticated', 'public.library_drills', 'DELETE')
     OR has_column_privilege('authenticated', 'public.library_drills', 'origin_department_id', 'SELECT')
     OR NOT has_column_privilege('authenticated', 'public.library_drills', 'content', 'SELECT')
     OR (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'library_drills') <> 1 THEN
    RAISE EXCEPTION 'POST: library_drills grants / policy not as intended.';
  END IF;
  FOREACH k IN ARRAY array['public.pull_library_drill(uuid)', 'public.library_drill_usage()'] LOOP
    IF has_function_privilege('anon', k, 'EXECUTE') OR NOT has_function_privilege('authenticated', k, 'EXECUTE')
       OR NOT (SELECT prosecdef FROM pg_proc WHERE oid = to_regprocedure(k)) THEN
      RAISE EXCEPTION 'POST: % privileges / definer wrong.', k;
    END IF;
  END LOOP;
  FOR k, v IN SELECT * FROM jsonb_each_text(v_pins) LOOP
    IF md5(pg_get_functiondef(to_regprocedure(k))) <> v THEN RAISE EXCEPTION 'POST: % changed.', k; END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.drill_plans WHERE library_id IS NOT NULL) THEN RAISE EXCEPTION 'POST: an existing drill plan was touched.'; END IF;
  SELECT count(*) INTO v_ver_after FROM public.station_presence WHERE verified;
  IF v_ver_after <> v_ver_before THEN RAISE EXCEPTION 'POST: the verified count moved.'; END IF;
END
$mig$;

NOTIFY pgrst, 'reload schema';

-- =====================================================================
-- STATE ROW (read-only) — paste this back with the apply.
-- =====================================================================
SELECT jsonb_build_object(
  'library_drills', (SELECT jsonb_object_agg(origin || '/' || state, n) FROM (SELECT origin, state, count(*) n FROM public.library_drills GROUP BY 1, 2) x),
  'codes', (SELECT jsonb_agg(code ORDER BY code) FROM public.library_drills),
  'library_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'library_drills'),
  'origin_dept_selectable', has_column_privilege('authenticated', 'public.library_drills', 'origin_department_id', 'SELECT'),
  'drill_plans_source_chk', (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'drill_plans_source_chk'),
  'rpcs', (SELECT jsonb_agg(p.proname || ' anon=' || has_function_privilege('anon', p.oid, 'EXECUTE') || ' auth=' || has_function_privilege('authenticated', p.oid, 'EXECUTE') ORDER BY p.proname)
             FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('pull_library_drill', 'library_drill_usage')),
  'total_public_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'fn_count', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'verified_presence', (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
